class Solution:
    def maximumLength(self, s: str) -> int:
        max_len = 0
        for i in set(s):
            start = [j for j in range(len(s)) if s.startswith(i, j)]
            if len(start) < 3:
                continue
            for j in range(len(start) - 2):
                for k in range(j + 2, len(start)):
                    length = min(start[j + 1] - start[j], start[k] - start[j + 1], start[k + 1] - start[k] if k + 1 < len(start) else len(s) - start[k])
                    max_len = max(max_len, length)
        return max_len if max_len > 0 else -1
